import os, csv

BASE = os.path.join("storage", "shared", "agency_lab")
CSV_DIR = os.path.join(BASE, "analyses", "csv")
MEANS = os.path.join(CSV_DIR, "transgen_means_v0_1.csv")
OUT   = os.path.join(CSV_DIR, "transgen_means_v0_1_normalized.csv")

def read_csv(path):
    with open(path, "r", encoding="utf-8", newline="") as f:
        return list(csv.DictReader(f))

def write_csv(path, rows):
    if not rows:
        return
    os.makedirs(os.path.dirname(path), exist_ok=True)
    with open(path, "w", encoding="utf-8", newline="") as f:
        w = csv.DictWriter(f, fieldnames=list(rows[0].keys()))
        w.writeheader(); w.writerows(rows)

def to_float(x):
    try:
        return float(x)
    except Exception:
        return None

def looks_like_denominator_col(cname: str) -> bool:
    lc = cname.lower()
    # Accept variants: include "max" and "collective" and "reward" and "round" or close approximations
    keys = ("max", "collective", "reward", "round")
    return all(k in lc for k in keys) or ("max_possible_collective_reward_per_round" in lc)

def looks_like_generation_col(cname: str) -> bool:
    return cname.lower() in ("generation","gen","g","generation_id")

def find_denominators_map() -> tuple[dict, str]:
    # Search candidate roots in priority order to avoid scanning everything if possible
    roots = [
      os.path.join("storage","shared","agency_lab","data","transgen_config"),
      os.path.join("storage","shared","agency_lab","data"),
      os.path.join("storage","progressor"),
      os.path.join("storage","shared","agency_lab"),
      "storage",
    ]
    visited = set()
    for root in roots:
        if not os.path.exists(root): continue
        for dirpath, dirnames, filenames in os.walk(root):
            # Avoid revisiting same dirs
            if dirpath in visited: continue
            visited.add(dirpath)
            for fn in filenames:
                if not fn.lower().endswith(".csv"): continue
                path = os.path.join(dirpath, fn)
                try:
                    rows = read_csv(path)
                    if not rows: continue
                    cols = list(rows[0].keys())
                    gen_col = next((c for c in cols if looks_like_generation_col(c)), None)
                    den_cols = [c for c in cols if looks_like_denominator_col(c)]
                    if gen_col and den_cols:
                        den_col = den_cols[0]  # pick first plausible
                        m = {}
                        for r in rows:
                            gi_raw = r.get(gen_col)
                            di_raw = r.get(den_col)
                            if gi_raw is None: continue
                            try:
                                gi = int(float(gi_raw))
                            except Exception:
                                continue
                            di = to_float(di_raw)
                            if di is None: continue
                            m[gi] = di
                        if m:
                            print("FOUND_DENOMS", path, "gens=", sorted(m.keys()))
                            return m, path
                except Exception:
                    # ignore unreadable files
                    pass
    return {}, ""

def main():
    if not os.path.exists(MEANS):
        print("ERROR means missing:", MEANS)
        return 1
    denom_map, denom_src = find_denominators_map()
    means = read_csv(MEANS)
    if not means:
        print("ERROR empty means:", MEANS)
        return 2

    cols = list(means[0].keys())
    gen_cols = ["generation","Generation","gen","Gen","generation_id"]
    trm_col = next((c for c in cols if c.lower()=="total_reward_mean" or ("total" in c.lower() and "reward" in c.lower() and "mean" in c.lower())), None)
    na_col  = next((c for c in cols if c.lower() in ("num_agents","agents","n_agents","nAgents")), None)

    out = []
    for r in means:
        g_raw = next((r.get(c) for c in gen_cols if r.get(c) not in (None,"")), None)
        if g_raw is None:
            continue
        try:
            g = int(float(g_raw))
        except Exception:
            continue
        trm = to_float(r.get(trm_col)) if trm_col else None
        den = denom_map.get(g)
        norm = (trm/den) if (trm is not None and den not in (None,0)) else ""
        na_raw = r.get(na_col) if na_col else ""
        pa = ""
        if trm is not None and na_raw not in ("",None):
            try:
                na = float(na_raw)
                if na > 0: pa = trm/na
            except Exception:
                pass
        out.append({
            "generation": g,
            "total_reward_mean": trm if trm is not None else "",
            "normalized_collective_reward_mean": norm,
            "num_agents": na_raw,
            "per_agent_reward_mean": pa if pa != "" else "",
        })
    write_csv(OUT, out)
    print("WROTE", OUT, "rows=", len(out), "denom_source=", (denom_src or "not_found_partial_or_empty"))
    return 0

if __name__ == "__main__":
    raise SystemExit(main())
